import { eq, inArray, sql } from 'drizzle-orm';
import { contentHash } from '../worker/catalog/hash.ts';
import type { connectDatabase } from '../worker/db/connection.ts';
import { instanceDeletions, instances, roomInventoryScans } from '../worker/db/schema.ts';
import type { Env } from '../worker/env.ts';
import { eraseInstance } from './instances.ts';
import { erasureBatch } from './limits.ts';

export type InventoryEnv = {
  GAME_ROOM: Env['GAME_ROOM'];
  CLOUDFLARE_ACCOUNT_ID?: string;
  GAME_ROOM_NAMESPACE_ID?: string;
  DURABLE_OBJECTS_READ_TOKEN?: string;
  // Generated by the local Vite config from the complete persisted GameRoom directory.
  LOCAL_ROOM_INVENTORY?: string;
};

// Persist one page at a time; retries never need to traverse the entire namespace again.
export async function reconcileRoomInventory(
  db: Pick<ReturnType<typeof connectDatabase>['db'], 'transaction'>,
  env: InventoryEnv,
) {
  const localIds: unknown =
    env.LOCAL_ROOM_INVENTORY === undefined
      ? undefined
      : JSON.parse(env.LOCAL_ROOM_INVENTORY);
  if (
    localIds !== undefined &&
    (!Array.isArray(localIds) ||
      localIds.some((id) => typeof id !== 'string' || !/^[a-f0-9]{64}$/.test(id)) ||
      new Set(localIds).size !== localIds.length)
  )
    throw new Error('INVALID_LOCAL_INVENTORY');
  if (
    localIds === undefined &&
    (!env.CLOUDFLARE_ACCOUNT_ID ||
      !env.GAME_ROOM_NAMESPACE_ID ||
      !env.DURABLE_OBJECTS_READ_TOKEN)
  )
    throw new Error('INVENTORY_CONFIGURATION_REQUIRED');
  const key = Array.isArray(localIds)
    ? 'local'
    : `${env.CLOUDFLARE_ACCOUNT_ID}:${env.GAME_ROOM_NAMESPACE_ID}`;
  return db.transaction(async (tx) => {
    await tx.execute(
      sql`select pg_advisory_xact_lock(hashtextextended(${`room-inventory:${key}`},0))`,
    );
    const pending = await tx
      .select()
      .from(instances)
      .where(eq(instances.roomInventoryComplete, false));
    const deletions = await tx.select().from(instanceDeletions);
    const [saved] = await tx
      .select()
      .from(roomInventoryScans)
      .where(eq(roomInventoryScans.id, key));
    let scan: typeof saved | undefined = saved;
    if (!scan && !pending.length && !deletions.some((job) => job.inventoryPending))
      return true;
    if (pending.some((instance) => instance.state === 'published'))
      throw new Error('INVENTORY_REQUIRES_PAUSE');
    const localHash = Array.isArray(localIds) ? await contentHash(localIds) : null;
    if (scan && scan.localHash !== localHash) {
      await tx.delete(roomInventoryScans).where(eq(roomInventoryScans.id, key));
      scan = undefined;
    }
    if (!scan) {
      [scan] = await tx
        .insert(roomInventoryScans)
        .values({ id: key, scopeIds: pending.map((scope) => scope.id), localHash })
        .returning();
    }
    if (!scan.complete) {
      let page: {
        success: boolean;
        result?: { id?: string }[];
        result_info?: { cursor?: string };
      };
      if (Array.isArray(localIds)) {
        const offset = Number(scan.cursor ?? 0);
        if (!Number.isSafeInteger(offset) || offset < 0)
          throw new Error('INVALID_LOCAL_INVENTORY_CURSOR');
        const end = offset + erasureBatch.inventory;
        page = {
          success: true,
          result: localIds.slice(offset, end).map((id: string) => ({ id })),
          result_info: { cursor: end < localIds.length ? String(end) : undefined },
        };
      } else {
        const url = new URL(
          `https://api.cloudflare.com/client/v4/accounts/${encodeURIComponent(env.CLOUDFLARE_ACCOUNT_ID ?? '')}/workers/durable_objects/namespaces/${encodeURIComponent(env.GAME_ROOM_NAMESPACE_ID ?? '')}/objects`,
        );
        url.searchParams.set('limit', String(erasureBatch.inventory));
        if (scan.cursor) url.searchParams.set('cursor', scan.cursor);
        const response = await fetch(url, {
          headers: { Authorization: `Bearer ${env.DURABLE_OBJECTS_READ_TOKEN}` },
          signal: AbortSignal.timeout(15000),
        });
        if (!response.ok) throw new Error('INVENTORY_UNAVAILABLE');
        page = await response.json();
      }
      if (
        !page.success ||
        !Array.isArray(page.result) ||
        page.result.length > erasureBatch.inventory
      )
        throw new Error('INVALID_INVENTORY');
      for (const entry of page.result) {
        if (!entry.id || !/^[a-f0-9]{64}$/.test(entry.id))
          throw new Error('INVALID_ROOM_ID');
        const room = env.GAME_ROOM.get(env.GAME_ROOM.idFromString(entry.id));
        const actual = await room.inventoryScope();
        if (!actual) continue;
        const deleted = deletions.find(
          (job) => job.owner === actual.owner && job.deletedAt,
        );
        if (deleted?.deletedAt) {
          await room.eraseRestoredInstance({
            id: deleted.instanceId,
            owner: deleted.owner,
            deletedAt: deleted.deletedAt,
          });
          continue;
        }
        const scope = pending.find(
          (instance) =>
            scan.scopeIds.includes(instance.id) && instance.owner === actual.owner,
        );
        if (scope) await room.registerInventory({ id: scope.id, owner: scope.owner });
        else if (actual.instanceId && scan.scopeIds.includes(actual.instanceId))
          throw new Error('INVENTORY_SCOPE_CONFLICT');
      }
      const cursor = page.result_info?.cursor ?? null;
      if (cursor && cursor === scan.cursor) throw new Error('INVENTORY_CURSOR_CONFLICT');
      await tx
        .update(roomInventoryScans)
        .set({ cursor, complete: !cursor })
        .where(eq(roomInventoryScans.id, key));
      if (cursor) return false;
    }
    const current = scan.scopeIds.length
      ? await tx.select().from(instances).where(inArray(instances.id, scan.scopeIds))
      : [];
    if (current.some((instance) => instance.state === 'published'))
      throw new Error('INVENTORY_REQUIRES_PAUSE');
    for (const instance of current)
      await tx.execute(
        sql`select quiz_game.confirm_room_inventory(${instance.id}::uuid)`,
      );
    const restored = deletions.filter((job) => job.inventoryPending);
    for (const deletion of restored.slice(0, erasureBatch.jobs)) {
      if (!(await eraseInstance(tx, env.GAME_ROOM, deletion.id))) return false;
      await tx
        .update(instanceDeletions)
        .set({ inventoryPending: false })
        .where(eq(instanceDeletions.id, deletion.id));
    }
    if (restored.length > erasureBatch.jobs) return false;
    await tx.delete(roomInventoryScans).where(eq(roomInventoryScans.id, key));
    return true;
  });
}
